#!/usr/bin/env python3
"""Read-only live Stage 09 GPU, training and evaluation dashboard.
Run on the laptop; uses one SSH session and the existing cloud Python.
No file writes, package installs, training launches or power operations.
"""
import argparse,json,shlex,shutil,subprocess,sys

REMOTE='"""Read-only Stage 09 terminal dashboard. Standard library; no project imports."""\nimport csv,json,math,os,re,statistics,subprocess,sys,time,unicodedata\nfrom datetime import datetime,timedelta,timezone\nfrom pathlib import Path\n\nROOT=Path(\'/root/autodl-tmp/microduck-double-balance\')\nART=ROOT/\'artifacts/double-balance-stage09\'\nCACHE={}\nWARNINGS=[]\nANSI=re.compile(r\'\\x1b\\[[0-?]*[ -/]*[@-~]\')\n\ndef clean(value):\n    return \'\'.join(c for c in ANSI.sub(\'\',str(value)) if c>=\' \' and c!=\'\\x7f\')\n\ndef fit(value,width):\n    value=clean(value);out=\'\';used=0\n    for c in value:\n        n=2 if unicodedata.east_asian_width(c) in \'WF\' else 1\n        if used+n>width-1:return out+\'…\'\n        out+=c;used+=n\n    return out\n\ndef read(path):\n    path=Path(path)\n    try:\n        stat=path.stat();stamp=(stat.st_mtime_ns,stat.st_size)\n        if path in CACHE and CACHE[path][0]==stamp:return CACHE[path][1]\n        data=json.loads(path.read_text());CACHE[path]=(stamp,data);return data\n    except FileNotFoundError:return {}\n    except (OSError,ValueError) as exc:\n        WARNINGS.append(\'读取失败 \'+path.name+\': \'+type(exc).__name__)\n        return {}\n\ndef number(value):\n    return isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value)\n\ndef fmt(value,digits=3):return f\'{value:.{digits}f}\' if number(value) else \'--\'\n\ndef ratio(success,count):\n    if not number(success) or not number(count) or count<=0:return \'--\'\n    return f\'{success:.0f}/{count:.0f}={100*success/count:.1f}%\'\n\ndef duration(seconds):\n    if not number(seconds):return \'--\'\n    seconds=max(0,int(seconds));return f\'{seconds//3600:02d}:{seconds//60%60:02d}:{seconds%60:02d}\'\n\ndef age(path):\n    try:return max(0,time.time()-Path(path).stat().st_mtime)\n    except OSError:return None\n\ndef tail(path,limit=32768):\n    try:\n        with Path(path).open(\'rb\') as stream:\n            stream.seek(0,2);size=stream.tell();offset=max(0,size-limit);stream.seek(offset)\n            data=stream.read().decode(\'utf-8\',errors=\'replace\')\n        if offset:data=data.partition(\'\\n\')[2]\n        return data.splitlines()\n    except OSError:return []\n\ndef iteration_rows(folder):\n    rows=[]\n    for line in tail(folder/\'iterations.jsonl\',512*1024):\n        try:\n            row=json.loads(line)\n            if isinstance(row,dict):rows.append(row)\n        except ValueError:pass\n    return rows[-100:]\n\ndef workers():\n    found=[]\n    for path in Path(\'/proc\').iterdir():\n        if not path.name.isdigit():continue\n        try:args=[p.decode(errors=\'replace\') for p in (path/\'cmdline\').read_bytes().split(b\'\\0\') if p]\n        except OSError:continue\n        if \'mjlab_microduck.double_balance_stage09\' not in args or \'--worker\' not in args:continue\n        def argument(name):\n            try:return args[args.index(name)+1]\n            except (ValueError,IndexError):return None\n        module=args.index(\'mjlab_microduck.double_balance_stage09\')\n        mode=args[module+1] if module+1<len(args) else \'?\'\n        output=argument(\'--output\')\n        found.append(dict(pid=int(path.name),mode=mode,profile=argument(\'--profile\'),\n                          protocol=argument(\'--protocol\'),output=Path(output) if output else None))\n    return found\n\ndef gpu_lines():\n    try:\n        process=subprocess.run([\'nvidia-smi\',\'--query-gpu=index,name,utilization.gpu,memory.used,memory.total,temperature.gpu,power.draw\',\n                                \'--format=csv,noheader,nounits\'],capture_output=True,text=True,timeout=3)\n        if process.returncode:return [\'GPU 读取失败: \'+clean(process.stderr)[:100]]\n        lines=[]\n        for row in csv.reader(process.stdout.splitlines()):\n            if len(row)!=7:continue\n            index,name,util,used,total,temp,power=[x.strip() for x in row]\n            try:memory=f\'{float(used)/1024:.2f}/{float(total)/1024:.2f} GiB ({100*float(used)/float(total):.1f}%)\'\n            except (ValueError,ZeroDivisionError):memory=f\'{used}/{total} MiB\'\n            lines += [f\'GPU {index} {name} | 利用率 {util}% | 显存 {memory}\',\n                      f\'温度 {temp}°C | 功耗 {power} W\']\n        return lines or [\'GPU 未返回数据\']\n    except (OSError,subprocess.TimeoutExpired) as exc:return [\'GPU 读取超时或不可用: \'+type(exc).__name__]\n\ndef latest_evaluations(campaign):\n    selected={};fresh={}\n    for key,item in campaign.get(\'evaluations\',{}).items():\n        report=read(item.get(\'path\',\'\'))\n        if report.get(\'status\')!=\'PASS\':continue\n        label,_,protocol=key.partition(\'/\')\n        if protocol not in (\'nominal\',\'dev\'):\n            if protocol.startswith(\'test-\'):fresh.setdefault(label,[]).append(report)\n            continue\n        if label==\'baseline\':model,step=\'baseline\',0\n        else:\n            match=re.fullmatch(r\'(F[0-3])-u(\\d+)\',label)\n            if not match:continue\n            model,step=match[1],int(match[2])\n        if (model,protocol) not in selected or step>selected[model,protocol][0]:selected[model,protocol]=(step,report)\n    return selected,fresh\n\ndef effect_lines(campaign):\n    data,fresh=latest_evaluations(campaign)\n    lines=[\'评估效果：N=nominal，D=dev；@后为该报告的训练步数\']\n    baseline=data.get((\'baseline\',\'dev\'),(0,{}))[1]\n    for model in (\'baseline\',\'F0\',\'F1\',\'F2\',\'F3\'):\n        nom=data.get((model,\'nominal\'));dev=data.get((model,\'dev\'))\n        if not nom and not dev:continue\n        ntext=f\'N@{nom[0]} \'+ratio(nom[1].get(\'successes\'),nom[1].get(\'episodes_count\')) if nom else \'N 待评估\'\n        dtext=f\'D@{dev[0]} \'+ratio(dev[1].get(\'successes\'),dev[1].get(\'episodes_count\')) if dev else \'D 待评估\'\n        delta=\'\'\n        if dev and model!=\'baseline\' and number(baseline.get(\'success_fraction\')) and number(dev[1].get(\'success_fraction\')):\n            delta=f\' Δ{100*(dev[1]["success_fraction"]-baseline["success_fraction"]):+.1f}pp\'\n        lines.append(f\'{model:8} {ntext} | {dtext}{delta}\')\n        if dev:\n            pose=dev[1].get(\'posture_summary\',{});margin=pose.get(\'tail_head_margin_bad_fraction\')\n            lines.append(\'         D含姿态 \'+ratio(pose.get(\'successes\'),pose.get(\'episode_count\'))+\n                         \' | |yaw| \'+fmt(pose.get(\'tail_abs_yaw_median_deg\'),2)+\'°\'+\n                         \' | 裕量不足 \'+(fmt(100*margin,1)+\'%\' if number(margin) else \'--\'))\n    if not data:lines.append(\'等待首份评估；缺失值显示 --，不会记为 0%\')\n    for label,reports in fresh.items():\n        count=sum(r.get(\'episodes_count\',0) for r in reports)\n        old=sum(r.get(\'successes\',0) for r in reports)\n        post=sum(r.get(\'posture_summary\',{}).get(\'successes\',0) for r in reports)\n        lines.append(f\'独立测试 {label}: 已完成{len(reports)}/3份 | 旧标准 {ratio(old,count)} | 含姿态 {ratio(post,count)}\')\n    lines.append(\'旧标准=原平衡验收；含姿态=同时满足新增头姿态与裕量要求。\')\n    lines.append(\'yaw/裕量为后5秒采样指标；评估在基线、250/500步完成后更新。\')\n    return lines\n\ndef render(active,gpu,now=None):\n    now=time.time() if now is None else now\n    campaign=read(ART/\'pilot/campaign.json\');ledger=read(ART/\'ledger.json\')\n    lines=[datetime.fromtimestamp(now,timezone(timedelta(hours=8))).strftime(\'Microduck Stage 09 | %m-%d %H:%M:%S 北京时间\')]\n    lines+=gpu\n    elapsed=ledger.get(\'elapsed_seconds\',0);start=ledger.get(\'started_epoch\')\n    if not number(start):\n        try:start=datetime.fromisoformat((ART/\'setup-start.txt\').read_text().strip()).timestamp()\n        except (OSError,ValueError):start=None\n    if number(start):\n        elapsed=max(elapsed if number(elapsed) else 0,now-start)\n        total=ledger.get(\'maximum_cloud_hours\',4)*3600;reserve=ledger.get(\'finalization_reserve_hours\',.75)*3600\n        lines.append(f\'预算 已用 {duration(elapsed)} | 训练窗口剩余 {duration(total-reserve-elapsed)} | 总剩余 {duration(total-elapsed)}\')\n    else:lines.append(\'预算起点尚未读取到\')\n    phases=[]\n    for worker in active:\n        if worker[\'mode\']==\'train\':label=\'训练 \'+str(worker[\'profile\'])\n        elif worker[\'mode\']==\'evaluate\':label=\'评估 \'+(worker[\'output\'].parent.name if worker[\'output\'] else \'?\')+\'/\'+str(worker[\'protocol\'])\n        else:label=worker[\'mode\']\n        phases.append(label+f\' (PID {worker["pid"]})\')\n    lines.append(\'当前 \'+(\'；\'.join(phases) if phases else \'未检测到工作进程，结合状态和日志判断\')+f\' | 已完成评估 {len(campaign.get("evaluations",{}))}份\')\n    reports={};charges=ledger.get(\'charged_updates\',{})\n    for model in (\'F0\',\'F1\',\'F2\',\'F3\'):\n        entry=campaign.get(\'profiles\',{}).get(model,{})\n        folder=Path(entry[\'segments\'][-1]) if entry.get(\'segments\') else None\n        reports[model]=(entry,folder,read(folder/\'training.json\') if folder else {})\n    completed=sum(report.get(\'experiment_completed_updates\',entry.get(\'completed\',0)) for entry,folder,report in reports.values())\n    lines.append(f\'PPO 完成 {completed}/2000 ({completed/20:.1f}%) | 已计尝试 {sum(charges.values())}/{ledger.get(\'maximum_total_updates\',2000)}（包括失败尝试）\')\n    names={\'INITIALIZING\':\'准备中\',\'RUNNING\':\'训练中\',\'TRAINING_COMPLETE\':\'该段完成\',\'PAUSED\':\'已暂停\',\'FAIL\':\'失败\'}\n    for model,(entry,folder,report) in reports.items():\n        n=report.get(\'experiment_completed_updates\',entry.get(\'completed\',0));status=report.get(\'status\',\'等待\')\n        age_s=age(folder/\'training.json\') if folder else None\n        suffix=f\' | 报告 {duration(age_s)}前\' if age_s is not None else \'\'\n        lines.append(f\'{model} {n:3}/500 ({n/5:5.1f}%) | 尝试 {charges.get(model,0):3}/{ledger.get(\'maximum_updates_by_profile\',{}).get(model,500)} | {names.get(status,status)}\'+suffix)\n        if report.get(\'error\') or report.get(\'reason\'):lines.append(\'   \'+str(report.get(\'error\') or report.get(\'reason\')))\n    current=next((w[\'profile\'] for w in active if w[\'mode\']==\'train\' and w[\'profile\'] in reports),None)\n    if current is None:\n        candidates=[(age(folder/\'training.json\'),model) for model,(entry,folder,report) in reports.items() if folder and report]\n        candidates=[(a,m) for a,m in candidates if a is not None]\n        if candidates:current=min(candidates)[1]\n    if current:\n        entry,folder,report=reports[current];row=report.get(\'latest_update\',{});history=iteration_rows(folder)\n        lines.append(f\'{current} 最近训练指标（奖励不等于成功率）：\')\n        seconds=[r[\'iteration_seconds\'] for r in history[-20:] if number(r.get(\'iteration_seconds\'))]\n        typical=statistics.median(seconds) if seconds else row.get(\'iteration_seconds\')\n        done=report.get(\'experiment_completed_updates\',entry.get(\'completed\',0));target=report.get(\'target_updates\')\n        eta=typical*max(0,target-done) if number(typical) and number(target) else None\n        lines.append(\'LR \'+(f\'{row["learning_rate"]:.6e}\' if number(row.get(\'learning_rate\')) else \'--\')+\n                     \' | 最近20次中位 \'+fmt(typical,2)+\'秒/更新 | 到当前节点约 \'+duration(eta)+\'（不含评估/保存）\')\n        reward=row.get(\'mean_episode_return_last_100\');old=history[-21].get(\'mean_episode_return_last_100\') if len(history)>20 else None\n        delta=f\'，较20次前 {reward-old:+.3f}\' if number(reward) and number(old) else \'\'\n        lines.append(\'近100回合平均回报 \'+fmt(reward)+delta+\' | 平均回合 \'+fmt(row.get(\'mean_episode_seconds_last_100\'),2)+\'秒\')\n        losses=row.get(\'losses\',{})\n        lines.append(\'损失 \'+(\' | \'.join(str(k)+\'=\'+fmt(v,5) for k,v in list(losses.items())[:4]) if losses else \'等待首个更新\'))\n        ep=row.get(\'episode\',{})\n        lines.append(\'头yaw奖励 \'+fmt(ep.get(\'Episode_Reward/stage09_head_yaw\'),5)+\' | 裕量奖励 \'+fmt(ep.get(\'Episode_Reward/stage09_head_margin\'),5)+\n                     \' | 保存重载 \'+str(report.get(\'save_reload_passed\',\'待完成\')))\n    else:lines.append(\'训练指标：尚无 PPO 更新报告；评估阶段 GPU 利用率也可能变化。\')\n    lines+=effect_lines(campaign)\n    lines.append(\'状态记录 \'+str(campaign.get(\'status\',\'尚未创建\'))+\'；INITIALIZING 字段可能贯穿运行，当前步骤见上方进程。\')\n    if campaign.get(\'error\'):lines.append(\'实验错误 \'+str(campaign[\'error\']))\n    logs=[w[\'output\'].with_suffix(\'.log\') for w in active if w.get(\'output\')]\n    if not logs:logs=list(ART.glob(\'campaign-*.log\'))\n    logs=[p for p in logs if p.exists()]\n    if logs:\n        latest=min(logs,key=lambda p:age(p) if age(p) is not None else float(\'inf\'))\n        lines.append(\'日志 \'+str(latest.relative_to(ART))+\' | \'+duration(age(latest))+\'前更新\')\n        recent=[clean(x) for x in tail(latest) if x.strip() and not x.startswith(\'Stage09Update=\')]\n        lines+=[\'  \'+x for x in recent[-2:]]\n    lines+=WARNINGS[-2:]\n    return lines\n\ndef main():\n    once=OPTIONS[\'once\'];interval=OPTIONS[\'interval\'];width=OPTIONS[\'width\'];height=OPTIONS[\'height\']\n    try:\n        while True:\n            begun=time.monotonic();WARNINGS.clear()\n            lines=render(workers(),gpu_lines())\n            # Keep GPU/progress visible on smaller terminals; --full shows every line.\n            if not OPTIONS[\'full\'] and len(lines)>height-2:\n                cutoff=max(12,height-3)\n                lines=lines[:cutoff]+[\'窗口较小，部分行省略；最大化终端或加 --full 显示完整内容。\']\n            if not once:sys.stdout.write(\'\\033[2J\\033[H\')\n            print(\'\\n\'.join(fit(line,width) for line in lines),flush=True)\n            print(f\'每 {interval:g} 秒刷新 | 只读监控 | Ctrl+C 退出监控，训练继续\',flush=True)\n            if once:break\n            time.sleep(max(.1,interval-(time.monotonic()-begun)))\n    except (KeyboardInterrupt,BrokenPipeError):pass\n\nif __name__==\'__main__\':main()\n'

def main():
    parser=argparse.ArgumentParser(description='Stage 09 只读实时监控')
    parser.add_argument('--interval',type=float,default=5,help='刷新间隔秒数，至少2秒')
    parser.add_argument('--once',action='store_true',help='仅输出一次，便于保存和分享')
    parser.add_argument('--full',action='store_true',help='显示全部行，适合最大化终端')
    args=parser.parse_args()
    if not 2<=args.interval<=60:parser.error('--interval 必须在2到60秒之间')
    size=shutil.get_terminal_size((110,45))
    options=dict(interval=args.interval,once=args.once,full=args.full,width=max(60,size.columns),height=max(20,size.lines))
    code='OPTIONS='+repr(options)+'\n'+REMOTE
    command=['ssh','-o','ConnectTimeout=10','-o','ServerAliveInterval=10','-o','ServerAliveCountMax=3',
             '-p','41381','root@connect.bjb1.seetacloud.com',
             shlex.join(['/root/autodl-tmp/microduck-double-balance/workspace/.venv/bin/python','-u','-'])]
    print('连接云端，只读监控；不会启动或重启训练。',flush=True)
    try:
        result=subprocess.run(command,input=code,text=True)
        if result.returncode:print('监控连接已结束，退出码 '+str(result.returncode)+'；可重新执行本监控命令。',file=sys.stderr)
        return result.returncode
    except KeyboardInterrupt:
        print('\n监控已退出；未向训练进程发送停止指令。');return 0

if __name__=='__main__':raise SystemExit(main())
